-- Golden relevance fixture (P1.E.2.2): ~90 curated items plus generated filler, 3k items in total.
-- Hand-picked catalogue sample until the migrated catalogue exists (P2.F re-runs the golden set).

-- Filler: deterministic, built from word lists that share no vocabulary with the golden queries.
CREATE TABLE filler_words AS SELECT * FROM (VALUES
  ('en', ARRAY['Crimson','Silent','Hollow','Amber','Iron','Velvet','Frozen','Distant','Paper','Neon','Rusty','Gentle','Broken','Scarlet','Wandering','Midnight','Golden','Shallow','Brittle','Lunar'],
         ARRAY['Harbor','Orchard','Signal','Lantern','Citadel','Meadow','Compass','Archive','Voyage','Garden','Carousel','Bridge','Station','Harvest','Mirror','Fortress','Parade','Tide','Workshop','Horizon']),
  ('pt-BR', ARRAY['Rubro','Calado','Oco','Ambarino','Férreo','Aveludado','Gelado','Remoto','Papel','Néon','Enferrujado','Suave','Partido','Escarlate','Errante','Meia-noite','Dourado','Raso','Frágil','Lunar'],
         ARRAY['Porto','Pomar','Sinal','Lanterna','Cidadela','Prado','Bússola','Arquivo','Viagem','Jardim','Carrossel','Ponte','Estação','Colheita','Espelho','Fortaleza','Desfile','Maré','Oficina','Horizonte']),
  ('es', ARRAY['Carmesí','Silente','Hueco','Ámbar','Férreo','Aterciopelado','Helado','Lejano','Papel','Neón','Oxidado','Suave','Roto','Escarlata','Errante','Medianoche','Dorado','Somero','Frágil','Lunar'],
         ARRAY['Puerto','Huerto','Señal','Linterna','Ciudadela','Pradera','Brújula','Archivo','Travesía','Jardín','Carrusel','Puente','Estación','Cosecha','Espejo','Fortaleza','Desfile','Marea','Taller','Horizonte'])
) v(locale, adj, noun);
SELECT md5('filler-' || g)::uuid, (ARRAY['game','movie','series','book'])[1 + g % 4], 'filler-' || g, 'Q' || (1000000 + g), (g * 37) % 50
FROM generate_series(1, 2918) g;
SELECT md5('filler-' || g)::uuid, w.locale,
  w.adj[1 + (g * 7) % 20] || ' ' || w.noun[1 + (g * 11 + g / 20) % 20] || CASE WHEN g % 3 = 0 THEN ' ' || (g / 3) ELSE '' END, 'hexascore'
FROM generate_series(1, 2918) g CROSS JOIN filler_words w;
SELECT md5('filler-' || g)::uuid, 'Alias ' || g, 'alias', 'hexascore' FROM generate_series(1, 2918, 5) g;
SELECT md5('filler-person-' || g)::uuid, 'person', 'filler-person-' || g, 'Q' || (2000000 + g), 'Quill Person ' || g
FROM generate_series(1, 300) g;
SELECT md5('filler-person-' || g)::uuid, 'en', 'Quill Person ' || g, 'hexascore' FROM generate_series(1, 300) g;
DROP TABLE filler_words;
ANALYZE;
